-- The society must already exist, and exactly once. These were imported with
-- their flat counts and portal accounts, so a missing one is a mistake to
-- stop on rather than paper over by inserting a second row — and a DUPLICATE
-- one is worse, because every statement below matches by name and would
-- quietly write to both.
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM societies WHERE name = 'Gaur Saundaryam';
  IF n = 0 THEN RAISE EXCEPTION 'no society named %', 'Gaur Saundaryam'; END IF;
  IF n > 1 THEN RAISE EXCEPTION '% societies named % — resolve the duplicate first', n, 'Gaur Saundaryam'; END IF;
END $$;

UPDATE societies SET status = 'active' WHERE name = 'Gaur Saundaryam';   -- address left as stored

