INSERT INTO agreements (id, pipeline_id, offer_id, prepared_at, prepared_by_id,
                        printed_at, notarized_at, signed_at, deviation_note,
                        executed_s3_key, executed_file_name, uploaded_at, uploaded_by_id)
SELECT 'bf-gaur-saundaryam-agreement', 'bf-gaur-saundaryam-pipe', 'bf-gaur-saundaryam-offer', '2026-02-21'::date, a.id,
       -- Printed and notarised are the same day, and it is the e-stamp
       -- certificate date on page 1 (the user, 2026-08-27). It can fall after
       -- the front-page date, which is a backdated effective date rather than
       -- a mistake.
       '2026-02-21'::date, '2026-02-21'::date,
       '2026-02-21'::date,
       -- How this deal's figures were arrived at, in the field named for it.
       -- These societies predate the system and share no single method, so
       -- the basis travels with the agreement rather than living in a CSV.
       'Commissioned before this system existed. There was no single method across these societies, so how this deal''s figures were arrived at is recorded here rather than assumed. Departures from the standard: extrapolation-theoretical. Agreement is a scanned PDF; its Annexure A and clause 6 were read by rendering the pages. Every figure reconciles to the paisa: 2,000 x 20W x 24h x 30 = 28,800 kWh/month, 62.43% of it is 17,979.84 kWh at Rs 6.67 = Rs 119,925.53, split 60/40 for FirsThing''s Rs 47,970.21. Its ''Devices & Hardware Rs 40,500 + Service Charges Rs 7,470.21'' is a presentational split of that same 40%, marked ''For Billing Purposes Use Only'', so this is a plain revenue share, not a device charge plus a cut. 2,362 lights installed against a 2,000 minimum, so the agreement''s ''increase proportionately'' clause applied and was honoured: the first invoice bills 2,362 x Rs 10.125 for 15 days, which is the annexure''s own Rs 20.25/light (40,500/2000) halved, and a full month comes to Rs 56,652.80 = Rs 47,970.21 x 2362/2000. Billing from 16 Apr 2026 - the first invoice covers 15 days of a 30-day April - so installation finished on or before 15 Apr (the user). Notarised and signed 21 Feb 2026. Tolerance +/-5%, stated in clause 6.',
       'Documents/Gaur_Saundaryam/2026-02/Agreements/Gaur_Saundaryam_Agreement_2026-02-21.pdf',
       'Gaur_Saundaryam_Agreement_2026-02-21.pdf',
       -- The scan reaches us the day after signing.
       ('2026-02-21'::date + 1), a.id
FROM admin_users a WHERE a.id = 'sys-data-import' ON CONFLICT DO NOTHING;

